def test_known_order():
    statuses = {1: 'shipped', 2: 'pending'}
    assert get_order_status(1, statuses) == 'shipped', 'must return the stored status for a known order_id'

def test_unknown_order_returns_none():
    statuses = {1: 'shipped'}
    assert get_order_status(99, statuses) is None, 'an unknown order_id must return None, not raise'

def test_annotation_uses_optional():
    from typing import Optional
    ann = get_order_status.__annotations__
    assert ann.get('return') == Optional[str], 'return type must be annotated as Optional[str] (or equivalently str | None)'

